def kernel_cholesky_base(
    n: size,
    A: DATA_TYPE[n, n] @ DRAM,
):
    for i in seq(0, n):
        # Off-diagonal elements in row i: j < i
        for j in seq(0, i):
            # Compute A[i, j] -= sum_{k=0}^{j-1} A[i, k] * A[j, k]
            for k in seq(0, j):
                A[i, j] = A[i, j] - A[i, k] * A[j, k]
            # Finish L[i, j] = A[i, j] / A[j, j]
            A[i, j] = A[i, j] / A[j, j]

        # Diagonal element A[i, i]:
        # A[i, i] -= sum_{k=0}^{i-1} A[i, k]^2
        for k in seq(0, i):
            A[i, i] = A[i, i] - A[i, k] * A[i, k]

